import heapq

def ugly_number_ii(n):
    heap = [1]
    seen = {1}
    factors = (2, 3, 5)

    value = 1
    for _ in range(n):
        value = heapq.heappop(heap)
        for f in factors:
            nxt = value * f
            if nxt not in seen:
                seen.add(nxt)
                heapq.heappush(heap, nxt)

    return value

